def lex_sort(letters):
    """Lexicographically sort letters."""
    return reduce(lambda a, b: a + b, letters).strip("-")

def main():
    s = input()
    m = int(input())
    allowed_indices = [tuple(map(int, line.split(' '))) for line in input().split('\n') if line]

