    allowed_indices = list(set(reduce(lambda a, b: a + b, allowed_indices)).difference(tuple()))
    for index in sorted(allowed_indices):
        for i in filter(lambda letter: (i, letter) in allowed_indices, range(len(s))):
            s = s[:i] + s[i+1]
            yield s
    print(sorted(set(s), key=lex_sort)[0])

