    # Check if the points form a cyclic quadrilateral
    # and if the point passes through all points of the quadrilateral
    for pi in (point1, point2, point3, point4):
        if sorted([pi[0], pi[1]]) in sorted([point1[0], point2[0], point3[0], point4[0]],
