def calculate_zigzag_product(points, p):
    x_p, y_p = p
    total_product = 1

    for (x_i, y_i) in points:
        if x_i == x_p and y_i > y_p:
            total_product *= (x_i * y_i + 2 * y_p * (y_i - y_p))
        elif x_i == x_p and y_i < y_p:
            total_product *= (x_i * y_i + 2 * y_p * (y_i - y_p))
        elif y_i == y_p and x_i > x_p:
            total_product *= (-y_i * x_i + 2 * x_p * (x_i - x_p))
        elif y_i == y_p and x_i < x_p:
