import sys, itertools

def ask_question(index, x):
    sys.stdout.write("? " + str(index) + " " + str(x) + "\n")
    sys.stdout.flush()
    return int(input())

def solve(L, n):
    divisors = sorted([i for i in range(1, int(L**0.5) + 1) if L % i == 0])
    function_values = [x % L for x in range(L)]

    if L % n == 0:
        raise Exception("Input is already a valid solution.")

    for length in divisors:
        if L // length < n:
            continue
        for start in range(0, L-length+1, length//n):
            for end in range(start+length//n, L, length):
                segment = (start, end)
                values = [function_values[i-start] for i in range(L) if segment[0] <= i < segment[1]]
                if len(set(values)) == n:
                    return [[start, end]] + solve(L-length, n-1)

    raise Exception("No valid solution found.")

def print_answers(start, end):
    sys.stdout.write("! " + str(end - start) + "\n")
    print(" ".join(str(x) for x in itertools.islice(itertools.count(start), end-start)))

def main():
    n, L = map(int, input().split())
    if n > len(divisors):
        raise Exception("n is not less than the number of divisors of L.")

