            rotten_bee = -(10**16)
            rotten_wasp = -(10**16)
            queue = deque([start])
            visited = set()
            while queue:
                curr = queue.popleft()
                if bees[curr] > rotten_bee:
                    rotten_bee = bees[curr]
                if wasps[curr] > rotten_wasp:
                    rotten_wasp = wasps[curr]
                visited.add(curr)
                for neighbor in adj_list[curr]:
                    if neighbor not in visited:
                        queue.append(neighbor)
            if rotten_bee > rotten_wasp:
                ugly_wasp_win_pairs.append((start, neighbors))

        max_wins = 0
        for pairs in ugly_wasp_win_pairs:
            current_pairs = pairs[:]
            for i in range(m - 1):
                i_changes = False
                for select, (u, v) in enumerate(current_pairs[i::m]):
                    if select % 2 == 0:
                        current_pairs[i//2].append(select + len(current_pairs) // m)
                    else:
                        current_pairs[i//2].append(select - len(current_pairs) // m)
                        i_changes = True
                if not i_changes:
                    break
            votes = 0
            for choice, _ in sorted(current_pairs[i//2]):
                votes += (n - 1 - i) // (m - 1)
            max_wins = max(max_wins, votes)
        ugly_wasp_wins.append(max_wins)
    return ugly_wasp_wins

