def canAchieveConfiguration(edges):
    def dfs(node, parent):
        connections = set([node])
        for nei in G[node]:
            if nei != parent:
                dfs(nei, node)
                connections |= set(G[node][nei].keys())
        nodes_to_change = [node]
        for nei in G[node]:
            for key in G[node][nei].keys():
                if nodes_to_change == [node, nei]:
                    return True
                nodes_to_change = nodes_to_change | set(G[node][nei][key].keys())
        return False

    n = len(edges)
    G = [[] for _ in range(n)]
    for u, v, val in edges:
        G[u-1].append({v-1: {u-1: val}})
        G[v-1].append({u-1: {v-1: val}})

    leaf_nodes = [i for i in range(n) if len(G[i]) == 1]
    if len(leaf_nodes) < 2:
        return "NO"

    leaf_set = set(leaf_nodes)
    for leaf1, leaf2 in combinations(leaf_nodes, 2):
        if dfs(leaf1-1, -1) == dfs(leaf2-1, -1):
            return "NO"

    return "YES"
