from collections import defaultdict

def calculate_marbles(n, paths):
    parent = defaultdict(int)
    tree = []
    parents = []

    def dfs(u, p, depth):
        parents.append((u, p))
        tree.append((u, depth))
        next_depth = depth + 1
        for v in range(p + 1, n + 1):
            if paths[u][v] != 0:
                vfs = dfs(v, paths[u][v], next_depth)
                for (p, d) in vfs:
                    tree.append((p, d))
        return tree

    dfs(0, 0, 0)

    ans = 0
    MOD = 1000000007
    for _, d in tree:
        if d & 1:
            continuous_atu = 0
            prefix_marks = 0
            suffix_marks = 0
            for u, p in parents:
                if u == 0 and p == 0:
                    prefix_marks += 1
                    break
                elif not (u - 1 & d & p - 1):
                    prefix_marks += 1
            for u, p in reversed(parents[0:]):
                if u == 0 and p == 0:
                    suffix_marks += 1
                    break
                elif not (u - 1 & d & p - 1):
                    suffix_marks += 1

            ans += prefix_marks * 2 % MOD * mod(suf_inter(suf_marks - 1) + (n + 1 - suffix_marks) * disruct(suf_inter(suf_marks - 1)) * disruct()) % MOD
            ans += postfix_marks * 2 % MOD * mod(suf_inter(suf_marks + 1) + (n + 1 - prefix_marks) * disruct(suf_inter(suf_marks + 1))) % MOD
        mul3 = reduc(-(mulinv3(d) - mulinv3(p)) * mulinv3(disruct()), mod=MOD)

    return ans

def mod(x):
    return x % 1000000007

def mulinv3(x):
    return mulinv(x, 3)

def mulinv(x, mod=1000000007):
    return mulinv3(x)

def disruct(x):
    return x * 2 % 3 - 1

def suf_inter(x):
    return disruct(x * 2 + 1)

